#pragma once

#include <filesystem>
#include <optional>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace test_design_eas_database {

  struct Student {
    sqlgen::PrimaryKey<std::string> SNo;
    std::string SName;
    sqlgen::Default<int, 1> Sex;
    std::optional<std::string> Birthday;  // datetime as string in SQLite
    std::optional<int> Major;
    sqlgen::Default<float, 0> Scorses;
    std::optional<std::string> Remark;

    static constexpr const char* schema = "Student";
  };

  struct Course {
    sqlgen::PrimaryKey<int> CID;
    std::string CName;
    sqlgen::Default<int, 1> Term;
    std::optional<int> CTime;
    sqlgen::Default<float, 0> Credit;

    static constexpr const char* schema = "Course";
  };

  struct Score {
    std::string SNo;
    int CID;
    std::optional<float> Score;

    static constexpr const char* schema = "Score";
  };

  void design_eas_database() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Create Student table
    conn.and_then(create_table<Student> | if_not_exists)
        .or_else([](const auto& err) {
          std::cerr << "Error creating Student table: " << err.what() << std::endl;
          return err;
        });

    // Create Course table
    conn.and_then(create_table<Course> | if_not_exists)
        .or_else([](const auto& err) {
          std::cerr << "Error creating Course table: " << err.what() << std::endl;
          return err;
        });

    // Create Score table
    conn.and_then(create_table<Score> | if_not_exists)
        .or_else([](const auto& err) {
          std::cerr << "Error creating Score table: " << err.what() << std::endl;
          return err;
        });
  }

}
```

**Key Points:**

1. **Student struct**: 
   - `SNo` as `PrimaryKey<std::string>` for varchar PRIMARY KEY
   - `SName` as `std::string` for NOT NULL varchar
   - `Sex`, `Scorses` as `Default<Type, Value>` for default values
   - Optional fields wrapped in `std::optional`

2. **Course struct**:
   - `CID` as `PrimaryKey<int>` for auto-increment primary key
   - `Credit` as `Default<float, 0>` for NOT NULL with default
   - Optional fields wrapped in `std::optional`

3. **Score struct**:
   - Composite primary key and foreign keys are typically handled through additional constraints in sqlgen (the library should handle these based on the struct definition and relationships)

4. **design_eas_database function**:
   - Connects to "test_db.sqlite"
   - Creates all three tables using `create_table` with `if_not_exists` flag
   - Uses monadic error handling with `and_then` and `or_else`

