Looking at the code structure and the provided examples, I need to implement a function that:
1. Connects to SQLite database
2. Creates tables if needed
3. Executes a query to find active users (those with posts between 2025-12-01 and 2025-12-31)
4. Returns the results as a vector of ActiveUser structs

Based on the test example and the sqlgen library patterns, here's the complete implementation:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <chrono>
#include <iomanip>
#include <sstream>

namespace query_active_users_posts {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  sqlgen::DateTime created_at;
};

struct ActiveUser {
  static constexpr const char* tablename = "ActiveUserView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

/**
 * Description: This function returns a list of active users who have posted within the last year.
 * Returns: std::vector<ActiveUser>.
 */
std::vector<ActiveUser> query_active_users_posts() {
    // Connect to SQLite database
    const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Create tables (sqlgen automatically creates tables when writing or can be created explicitly)
    // This ensures the tables exist
    sqlgen::create_table<User>(conn);
    sqlgen::create_table<Post>(conn);

    // Execute the SQL query to find active users
    const std::string sql = R"(
        SELECT DISTINCT u.user_id, u.username
        FROM User u
        INNER JOIN Post p ON u.user_id = p.user_id
        WHERE p.created_at >= DATE('2025-12-01') AND p.created_at <= DATE('2025-12-31')
    )";

    // Execute the query and read the results into ActiveUser structs
    auto result = sqlgen::execute<std::vector<ActiveUser>>(conn, sql);

    // Return the result or an empty vector if there was an error
    if (result) {
        return result.value();
    }

    return std::vector<ActiveUser>{};
}

}  // namespace query_active_users_posts
```

This implementation:
1. **Connects** to the SQLite database "test_db.sqlite" using `sqlgen::sqlite::connect()`
2. **Creates tables** for User and Post using `sqlgen::create_table<>()`
3. **Executes the SQL query** using the provided reference SQL that finds users with posts between December 1-31, 2025
4. **Returns results** as a `std::vector<ActiveUser>`, which matches the ActiveUser struct format with user_id and username fields

The function uses the sqlgen library's pattern of executing SQL queries and automatically mapping the results to the appropriate struct types.

