Looking at the code fragments and the requirements, I need to implement a function that uses `sqlgen` to dynamically construct a SQL query based on optional filters. Here's the complete implementation:

```cpp
#pragma once

#include <optional>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_search_books_by_criteria {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    // Connect to the database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Start with a base SELECT query selecting all columns from Book table
    auto query = sqlgen::dynamic::select("Book", {"book_id", "title", "author", "year", "genre", "price"});

    // Build WHERE conditions dynamically based on provided filters
    std::vector<sqlgen::dynamic::Condition> conditions;

    // Add title LIKE filter if provided
    if (filters.title_keyword.has_value()) {
        conditions.push_back(
            sqlgen::dynamic::like("title", "%" + filters.title_keyword.value() + "%")
        );
    }

    // Add year >= filter if provided
    if (filters.min_year.has_value()) {
        conditions.push_back(
            sqlgen::dynamic::gte("year", std::to_string(filters.min_year.value()))
        );
    }

    // Add genre = filter if provided
    if (filters.genre.has_value()) {
        conditions.push_back(
            sqlgen::dynamic::eq("genre", filters.genre.value())
        );
    }

    // Add price <= filter if provided
    if (filters.max_price.has_value()) {
        conditions.push_back(
            sqlgen::dynamic::lte("price", std::to_string(filters.max_price.value()))
        );
    }

    // Apply WHERE clause if any conditions exist
    if (!conditions.empty()) {
        query = query.where(sqlgen::dynamic::and_cond(conditions));
    }

    // Execute the query and return results
    auto result = conn.and_then(sqlgen::read<std::vector<Book>>(query));

    if (result) {
        return result.value();
    } else {
        // Return empty vector if query fails
        return std::vector<Book>{};
    }
}

}  // namespace query_search_books_by_criteria
```

This implementation:

1. **Connects to the database** using `sqlgen::sqlite::connect("test_db.sqlite")`
2. **Creates a base SELECT query** using `sqlgen::dynamic::select()` to select all columns from the Book table
3. **Dynamically builds WHERE conditions** based on which optional filters are provided:
   - Uses `sqlgen::dynamic::like()` for title keyword matching with wildcards
   - Uses `sqlgen::dynamic::gte()` for year >= comparison
   - Uses `sqlgen::dynamic::eq()` for exact genre matching
   - Uses `sqlgen::dynamic::lte()` for price <= comparison
4. **Combines conditions** using `sqlgen::dynamic::and_cond()` if any filters are present
5. **Executes the query** using `sqlgen::read<std::vector<Book>>()` and returns the results
6. **Handles errors** by returning an empty vector if the query fails

