#pragma once

#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace schema_manage_indexes {

  struct Product {
    sqlgen::PrimaryKey<int> product_id;
    std::string sku;
    std::string name;
    std::string category;
    double price;
  };

  bool manage_indexes() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to the database and create table
    auto result = sqlgen::sqlite::connect("test_db.sqlite")
                      .and_then(create_table<Product> | if_not_exists)
                      // Create standard index on category
                      .and_then(create_index<"idx_product_category", Product>(
                                    "category"_c) |
                                if_not_exists)
                      // Create unique index on sku
                      .and_then(create_unique_index<"idx_product_sku", Product>(
                                    "sku"_c) |
                                if_not_exists)
                      // Create composite index on (name, price)
                      .and_then(create_index<"idx_product_name_price", Product>(
                                    "name"_c, "price"_c) |
                                if_not_exists);

    // Check if all operations succeeded
    if (result) {
      return true;
    } else {
      // Log error if needed
      return false;
    }
  }

}  // namespace schema_manage_indexes

