Looking at the code fragments and the requirements, I need to implement a soft delete function that:
1. Connects to SQLite database "test_db.sqlite"
2. Updates `is_deleted` to 1 and sets `deleted_at` timestamp
3. Uses a transaction for batched updates

Based on the code fragments showing the sqlgen API, here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace soft_delete_records {

struct Document {
  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    if (ids.empty()) {
        return true;
    }

    // Connect to the SQLite database
    auto conn_result = sqlgen::sqlite::Connection::make("test_db.sqlite");
    if (!conn_result) {
        return false;
    }
    auto conn = std::move(conn_result.value());

    // Begin transaction
    auto tx_result = conn->begin_transaction();
    if (!tx_result) {
        return false;
    }

    // Build the UPDATE SQL statement with IN clause
    // UPDATE Document SET is_deleted = 1, deleted_at = CURRENT_TIMESTAMP WHERE doc_id IN (?, ?, ...)
    std::string placeholders;
    for (size_t i = 0; i < ids.size(); ++i) {
        if (i > 0) {
            placeholders += ", ";
        }
        placeholders += "?";
    }

    std::string sql = "UPDATE Document SET is_deleted = 1, deleted_at = CURRENT_TIMESTAMP WHERE doc_id IN (" + placeholders + ")";

    // Prepare the statement
    auto stmt_result = conn->prepare_statement(sql);
    if (!stmt_result) {
        conn->rollback();
        return false;
    }
    auto stmt = std::move(stmt_result.value());

    // Bind the doc_id values
    for (size_t i = 0; i < ids.size(); ++i) {
        int res = sqlite3_bind_int(stmt.get(), static_cast<int>(i + 1), ids[i]);
        if (res != SQLITE_OK) {
            conn->rollback();
            return false;
        }
    }

    // Execute the statement
    int res = sqlite3_step(stmt.get());
    if (res != SQLITE_OK && res != SQLITE_DONE) {
        conn->rollback();
        return false;
    }

    // Commit the transaction
    auto commit_result = conn->commit();
    if (!commit_result) {
        conn->rollback();
        return false;
    }

    return true;
}

}  // namespace soft_delete_records
```

