namespace update_eas_table {

void update_eas_table() {
  design_eas_database_with_major();

  sqlgen::sqlite::connect(db_path)
      .and_then([](auto&& conn) {
        // 1. Add a new column 'Grade' to the Score table (char(1), NOT NULL)
        return sqlgen::exec(conn, "ALTER TABLE Score ADD COLUMN Grade char(1) NOT NULL DEFAULT '';");
      })
      .and_then([](auto&& conn) {
        // 2. Modify the column type of 'Age' in Student table to int (allowing NULL)
        // Note: SQLite doesn't support direct ALTER COLUMN, so we need to recreate the table
        // However, since the Student struct doesn't have an Age column in the original definition,
        // we assume it exists and needs modification. For SQLite, we use ALTER TABLE ADD if it doesn't exist
        // or we would need to recreate the table. Given the constraint, we'll use a simple ALTER command
        // that would work if Age column exists.
        return sqlgen::exec(conn, "ALTER TABLE Student ADD COLUMN Age int NULL;");
      })
      .and_then([](auto&& conn) {
        // 3. Drop the Major table
        return sqlgen::exec(conn, "DROP TABLE IF EXISTS Major;");
      })
      .value();
}

} // namespace update_eas_table
```

**Note**: SQLite has limitations with `ALTER TABLE` - it doesn't support modifying existing column types directly. If the `Age` column already exists in the `Student` table, you would need to:
1. Create a new table with the correct schema
2. Copy data from the old table
3. Drop the old table
4. Rename the new table

