```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace upsert_user_profile {

struct UserProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

/**
 * @brief Insert or update a user profile in the database.
 *
 * @param u The user profile to insert or update.
 * @return true If the operation is successful.
 * @return false If the operation fails.
 */
bool upsert_user_profile(const UserProfile& u) {
  // Connect to SQLite database
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  if (!conn) {
    return false;
  }

  // SQLite supports INSERT OR REPLACE for upsert operations
  const std::string sql = 
    "INSERT OR REPLACE INTO UserProfile (user_id, bio, avatar_url) VALUES (?, ?, ?)";

  // Prepare the statement
  auto stmt_result = conn->prepare_statement(sql);
  if (!stmt_result) {
    return false;
  }

  auto stmt = stmt_result.value();

  // Bind the values
  // Bind user_id (position 1)
  if (sqlite3_bind_int(stmt.get(), 1, u.user_id.get()) != SQLITE_OK) {
    return false;
  }

  // Bind bio (position 2)
  if (u.bio.has_value()) {
    if (sqlite3_bind_text(stmt.get(), 2, u.bio->c_str(), 
                         static_cast<int>(u.bio->size()), SQLITE_TRANSIENT) != SQLITE_OK) {
      return false;
    }
  } else {
    if (sqlite3_bind_null(stmt.get(), 2) != SQLITE_OK) {
      return false;
    }
  }

  // Bind avatar_url (position 3)
  if (u.avatar_url.has_value()) {
    if (sqlite3_bind_text(stmt.get(), 3, u.avatar_url->c_str(), 
                         static_cast<int>(u.avatar_url->size()), SQLITE_TRANSIENT) != SQLITE_OK) {
      return false;
    }
  } else {
    if (sqlite3_bind_null(stmt.get(), 3) != SQLITE_OK) {
      return false;
    }
  }

  // Execute the statement
  auto res = sqlite3_step(stmt.get());
  if (res != SQLITE_OK && res != SQLITE_ROW && res != SQLITE_DONE) {
    return false;
  }

  return true;
}

} // namespace upsert_user_profile
```

This implementation:

1. **Connects to the database** using `sqlgen::sqlite::connect("test_db.sqlite")`
2. **Uses `INSERT OR REPLACE`** which is SQLite's native upsert syntax - it will insert if the primary key doesn't exist, or replace the entire row if it does
3. **Prepares the SQL statement** using the connection's `prepare_statement` method
4. **Binds parameters** to the prepared statement:
   - `user_id` as an integer (position 1)
   - `bio` as text or NULL if not present (position 2)
   - `avatar_url` as text or NULL if not present (position 3)
5. **Executes the statement** using `sqlite3_step`
6. **Returns true on success, false on any failure**

The function properly handles optional fields by binding NULL when the `std::optional` values are not present.

