#include <vector>

namespace generate_sql_dry_run {

struct A {
  sqlgen::PrimaryKey<int> id;
  std::string name;
};

struct B {
  sqlgen::PrimaryKey<int> id;
  int a_id;
  double score;
};

/**
 * This function demonstrates how to build a conditional SQL query.
 * It joins tables A and B, filtering for records where score > 10 and name contains 'x'.
 * Returns: std::string.
 */
std::string generate_sql_dry_run() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Build a complex query with joins, where, order_by, and limit
  // The query joins tables A and B, filters by score > 10 and name contains 'x',
  // orders by score descending, and limits to 100 results
  const auto sql = sqlite::to_sql(
      sqlgen::read<std::vector<B>> |
      join<A>("a_id"_c == "A.id"_c) |
      where("score"_c > 10.0 && "name"_c.like("%x%")) |
      order_by("score"_c.desc()) |
      limit(100)
  );

  return sql;
}

}  // namespace generate_sql_dry_run
```

This implementation:
1. **Uses sqlgen column literals** (`"column_name"_c`) for building queries
2. **Constructs a join** between tables A and B on the foreign key relationship
3. **Adds where clauses** filtering for `score > 10` and `name` containing 'x'
4. **Adds order_by** clause to sort by score in descending order
5. **Adds limit** clause to limit results to 100 records
6. **Uses `sqlite::to_sql`** to generate the SQL string without executing it (dry run)
7. **Returns the generated SQL string** for debugging/verification purposes

The function demonstrates the dry run capability by using `to_sql` which generates the SQL statement as a string without actually executing it against the database.

