Looking at the code fragments and the requirements, I need to implement an `upsert_inventory_items` function that:

1. Connects to SQLite database "test_db.sqlite"
2. Creates the Inventory table if it doesn't exist
3. Performs an INSERT OR REPLACE operation
4. Returns true if inserted (new), false if replaced (already existed)

Based on the code fragments, I can see the `sqlgen` library uses a fluent API with `connect()`, `create_table`, and various operations. For detecting if an item already existed, I'll need to check if the item exists before the upsert operation.

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace upsert_inventory_items {

struct Inventory {
  sqlgen::PrimaryKey<int> item_id;
  std::string name;
  int quantity;
};

/**
 * This function demonstrates how to use upsert (insert or replace) statements in sqlgen write API.
 * It inserts or replaces the given inventory items in the Inventory table.
 * Returns: true if the item is inserted, false if the item is already in the table.
 */
bool upsert_inventory_items(Inventory item) {
  using namespace sqlgen;

  // Connect to the database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }

  auto conn = std::move(conn_result.value());

  // Create table if it doesn't exist
  auto create_result = conn->execute(create_table<Inventory> | if_not_exists);
  if (!create_result) {
    return false;
  }

  // Check if item already exists
  bool item_exists = false;
  auto read_result = conn->read(
    read<std::vector<Inventory>> | 
    where(field<"item_id", Inventory> == item.item_id())
  );

  if (read_result) {
    auto existing_items = read_result.value();
    item_exists = !existing_items.empty();
  }

  // Perform INSERT OR REPLACE
  auto upsert_result = conn->execute(
    insert_or_replace<Inventory>,
    std::vector<Inventory>{item}
  );

  if (!upsert_result) {
    return false;
  }

  // Return true if item was newly inserted, false if it was replaced
  return !item_exists;
}

}  // namespace upsert_inventory_items
```

