```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace analyze_social_network {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Friendship {
  int user1_id;
  int user2_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze who and whom are friends in the social network.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl() {
    using namespace sqlgen;

    // Connect to the SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // SQL query to join Friendship with User table twice to get both usernames
    const std::string sql = R"(
        SELECT u1.username, u2.username
        FROM Friendship f
        INNER JOIN User u1 ON f.user1_id = u1.user_id
        INNER JOIN User u2 ON f.user2_id = u2.user_id
    )";

    // Execute the query and convert results to FriendConnection structs
    auto result = sqlgen::query(conn, sql)
        .and_then(to<std::vector<FriendConnection>>);

    // Return the result, or empty vector if there's an error
    if (result) {
        return result.value();
    } else {
        return std::vector<FriendConnection>();
    }
}

}  // namespace analyze_social_network
```

