Based on the provided code fragments and the structure of the `sqlgen` library, here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace join_orders_customers_payments {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  int customer_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct Payment {
  sqlgen::PrimaryKey<int> payment_id;
  int order_id;
  double amount;
};

struct Consolidated {
  sqlgen::PrimaryKey<int> order_id;
  std::string customer_name;
  double amount;
};

/**
 * This function demonstrates how to join three tables (Orders, Customers, and Payments)
 * and return a consolidated view with order_id, customer_name, and amount.
 * It orders the results by amount in descending order.
 * Returns: std::vector<Consolidated>.
 */
std::vector<Consolidated> join_orders_customers_payments() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the SQL query with inner joins
  const auto sql = R"(
    SELECT o.order_id, c.name as customer_name, p.amount
    FROM Orders o
    INNER JOIN Customers c ON o.customer_id = c.customer_id
    INNER JOIN Payments p ON o.order_id = p.order_id
    ORDER BY p.amount DESC
  )";

  // Execute the query and return the consolidated results
  auto result = sqlgen::read<std::vector<Consolidated>>(conn, sql);

  return result.value_or(std::vector<Consolidated>{});
}

}  // namespace join_orders_customers_payments
```

This implementation:

1. **Connects to the SQLite database** `test_db.sqlite` using `sqlgen::sqlite::connect()`
2. **Performs inner joins** across the three tables:
   - Joins `Orders` (o) with `Customers` (c) on `customer_id`
   - Joins the result with `Payments` (p) on `order_id`
3. **Orders by payment amount descending** using `ORDER BY p.amount DESC`
4. **Returns consolidated records** with the structure `{order_id, customer_name, amount}` mapped to the `Consolidated` struct
5. Uses `.value_or()` to handle potential errors and return an empty vector if the query fails

