Looking at the code fragments and the `sqlgen` library API, I need to implement a function that:

1. Connects to a SQLite database
2. Creates Parent and Child tables with foreign key cascade constraints
3. Inserts test data
4. Deletes a parent record
5. Verifies that child records are automatically deleted

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * @param parent_id The ID of the parent record to delete.
 * Returns: true if the cascade delete worked as expected, false otherwise.
 */
bool cascade_delete_demo(int parent_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = conn_result.value();

  // Enable foreign key constraints in SQLite (required for cascade delete)
  auto fk_result = conn->execute("PRAGMA foreign_keys = ON;");
  if (!fk_result) {
    return false;
  }

  // Drop tables if they exist (for clean demo)
  (drop<Child> | if_exists)(conn);
  (drop<Parent> | if_exists)(conn);

  // Create Parent table
  auto parent_create = (create_table<Parent> | if_not_exists)(conn);
  if (!parent_create) {
    return false;
  }

  // Create Child table with foreign key constraint
  auto child_create = (create_table<Child> | if_not_exists)(conn);
  if (!child_create) {
    return false;
  }

  // Insert parent record
  std::vector<Parent> parents = {
      Parent{.parent_id = parent_id, .name = "Test Parent"}
  };
  auto parent_write = sqlgen::write(conn, parents);
  if (!parent_write) {
    return false;
  }

  // Insert child records with the same parent_id
  std::vector<Child> children = {
      Child{.child_id = 1, .parent_id = parent_id, .note = "Child 1"},
      Child{.child_id = 2, .parent_id = parent_id, .note = "Child 2"}
  };
  auto child_write = sqlgen::write(conn, children);
  if (!child_write) {
    return false;
  }

  // Verify children exist before deletion
  auto children_before = sqlgen::read<std::vector<Child>>(conn);
  if (!children_before || children_before.value().size() != 2) {
    return false;
  }

  // Delete the parent record
  auto delete_result = (delete_from<Parent> | where("parent_id"_c == parent_id))(conn);
  if (!delete_result) {
    return false;
  }

  // Verify children are automatically deleted (cascade delete)
  auto children_after = sqlgen::read<std::vector<Child>>(conn);
  if (!children_after) {
    return false;
  }

  // If cascade delete worked, there should be no child records left
  return children_after.value().empty();
}

}  // namespace cascade_delete_demo
```

This implementation:

1. **Connects** to "test_db.sqlite" using `sqlgen::sqlite::connect()`
2. **Enables foreign key constraints** with `PRAGMA foreign_keys = ON;` (required for SQLite to enforce cascade delete)
3. **Creates tables** using `create_table<T>` with the foreign key relationship already defined in the `Child` struct
4. **Inserts test data** - one parent and two children using `sqlgen::write()`
5. **Deletes the parent** using `delete_from<Parent>` with a where clause
6. **Verifies cascade behavior** by reading child records and checking if they were automatically deleted
7. **Returns true** if the child records are gone (cascade worked), **false** otherwise

