 * @returns true if the update operations are successful, and false otherwise.
 */
bool update_set_operations(int acc_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = std::move(conn_result.value());

  // Create the Account table if it doesn't exist
  auto create_result = conn->execute(create_table<Account> | if_not_exists);
  if (!create_result) {
    return false;
  }

  // Insert a test account if it doesn't exist
