Looking at the code fragments and the task requirements, I need to implement a function that:
1. Connects to SQLite database "test_db.sqlite"
2. Uses COALESCE to select `COALESCE(nickname, 'Anonymous')` from the Profile table
3. Returns the result as a vector of `NicknameResult`

Based on the sqlgen library patterns shown in the code fragments, here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <optional>

namespace coalesce_function {

struct Profile {
  sqlgen::PrimaryKey<int> id;
  std::optional<std::string> nickname;
};

struct NicknameResult {
  std::string display_name;
};

/**
 * This function demonstrates COALESCE usage.
 * Returns: vector<NicknameResult>
 */
inline std::vector<NicknameResult> coalesce_function() {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Construct a query using COALESCE function
    // COALESCE(nickname, 'Anonymous') will return nickname if it's not NULL,
    // otherwise it will return 'Anonymous'
    auto query = sqlgen::select(
        sqlgen::coalesce(
            sqlgen::field<&Profile::nickname>(),
            sqlgen::literal("Anonymous")
        ).as<&NicknameResult::display_name>()
    ).from<Profile>();

    // Execute the query and return the results
    auto results = conn->execute(query);

    return results;
}

}  // namespace coalesce_function
```

