 * Returns: std::vector<Score>.
 */
std::vector<Score> order_by_descending() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to the SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // Construct query with descending order by points
    auto result = conn | sqlgen::read<std::vector<Score>> | 
                  order_by("points"_c.desc());

    return result;
}

}  // namespace order_by_descending

