      .table = sqlgen::dynamic::Table{.name = "Product"},
      .sets = {sqlgen::dynamic::Update::Set{
        .col = sqlgen::dynamic::Column{.name = "stock"},
        .to = sqlgen::dynamic::Operation{
          sqlgen::dynamic::Operation::Plus{
            .op1 = std::make_shared<sqlgen::dynamic::Operation>(
              sqlgen::dynamic::Column{.name = "stock"}
            ),
            .op2 = std::make_shared<sqlgen::dynamic::Operation>(
              sqlgen::dynamic::Value{sqlgen::dynamic::Int{.val = qty}}
            )
          }
