#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <unordered_map>

namespace update_inventory_stock {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int stock;
};

/**
 * @brief Update inventory stock based on a shipment.
 * @param received A map of {product_id, quantity_received}.
 * @return true If all updates are successful, false otherwise.
 */
bool update_inventory_stock(const std::unordered_map<int, int>& received) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the database
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) return false;

  // Ensure the Product table exists
  conn_res.and_then(create_table<Product> | if_not_exists);

  // Begin a transaction
  auto txn_res = begin_transaction(conn_res.value());
  if (!txn_res) return false;
  auto txn = txn_res.value();

  // Update stock for each product
  for (const auto& [pid, qty] : received) {
    // Create an UPDATE statement: UPDATE Product SET stock = stock + qty WHERE product_id = pid
    auto update_stmt = sqlgen::dynamic::Update{
      .table = sqlgen::dynamic::Table{.name = "Product"},
      .sets = {sqlgen::dynamic::Update::Set{
        .col = sqlgen::dynamic::Column{.name = "stock"},
        .to = sqlgen::dynamic::Operation{
          sqlgen::dynamic::Operation::Plus{
            .op1 = std::make_shared<sqlgen::dynamic::Operation>(
              sqlgen::dynamic::Column{.name = "stock"}
            ),
            .op2 = std::make_shared<sqlgen::dynamic::Operation>(
              sqlgen::dynamic::Value{sqlgen::dynamic::Int{.val = qty}}
            )
          }
        }
      }},
      .where = sqlgen::dynamic::Condition{
        sqlgen::dynamic::Condition::Equal{
          .op1 = sqlgen::dynamic::Operation{
            sqlgen::dynamic::Column{.name = "product_id"}
          },
          .op2 = sqlgen::dynamic::Operation{
            sqlgen::dynamic::Value{sqlgen::dynamic::Int{.val = pid}}
          }
        }
      }
    };

    // Execute the update
    auto exec_res = exec(txn, update_stmt);
    if (!exec_res) {
      rollback(txn);
      return false;
    }
  }

  // Commit the transaction
  auto commit_res = commit(txn);
  return commit_res.has_value();
}

}  // namespace update_inventory_stock

