#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace project_time_tracking {

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
};

struct TimeLog {
  sqlgen::PrimaryKey<int> log_id;
  int project_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> end_time;
};

struct TimeMetrics {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
  int day;
  int month;
  int year;
  int hour;
  int minute;
  int second;
  double duration_days;
};

/**
 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite").value();

  // Build the query with inner join and temporal operations
  auto query = 
      select_from<Project>(
          "project_id"_c,
          "name"_c,
          day("start_time"_c).as<"day">(),
          month("start_time"_c).as<"month">(),
          year("start_time"_c).as<"year">(),
          hour("start_time"_c).as<"hour">(),
          minute("start_time"_c).as<"minute">(),
          second("start_time"_c).as<"second">(),
          days_between("start_time"_c, "end_time"_c).as<"duration_days">()
      ) |
      inner_join<TimeLog>("project_id"_c) |
      to<std::vector<TimeMetrics>>;

  // Execute the query and return results
  auto result = query(conn).value();

  return result;
}

}  // namespace project_time_tracking
